def transform(g):
    h=len(g); w=len(g[0])
    n=(w+2)//3
    b=[[g[i][j*3+1 if j<n-1 else w-1] for i in range(1,h,2)] for j in range(n)]
    p=[3,4,2,0,1][:n]
    b=[b[p[j]] for j in range(n)]
    out=[]
    for i in range(h):
        if i%2==0: out.append([6]*w)
        else:
            k=i//2
            row=[]
            for j in range(n):
                row += [6,b[j][k],0] if j<n-1 else [6,b[j][k]]
            out.append(row)
    return out
